"""Render the frozen November 20 audit as a readable, static Pages report."""
import html, json, statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def esc(x):return html.escape(str(x))
def dollar(x):return '—' if x is None else f'${x:,.2f}'
def pct(x):return '—' if x is None else f'{x*100:.2f}%'
def num(x):return '—' if x is None else f'{x:.2f}'
def interval(x):return 'Insufficient blocks' if x is None else ' to '.join(map(pct,x))
def table(head,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def render(r):
    body=[]
    def section(title,text):body.append('<section><h2>'+esc(title)+'</h2>'+text+'</section>')
    def p(t):return '<p>'+esc(t)+'</p>'
    section('Decision: pause new same-day entries',p('Keep the eight-hour collection schedule, monthly/long-horizon paper tests and all five registered exit targets. No target winner is supported. Same-day entry pauses are operational: two-hour exits are not achievable with this collector, even though that horizon currently has a positive marked result. Existing orders and positions continue to be monitored; no old fills, losses or entry versions change.')+table(['Decision','Next-period hypothesis','Evidence required to reverse'],[
        ['PAUSE same-day maker + taker','Sparse polling cannot deliver the registered two-hour exit. Earmarked capital stays idle.','A prospective execution design with timestamped executable books; at least seven days showing no material >1h exit delays, audited liquidity and explicit new validation phase.'],
        ['KEEP month / long; no increased sizing','Longer holding budgets may remain workable while learning fill costs. Current results do not establish an edge.','Pause affected sleeve if history remains incomplete next run, liquidity prevents exits, or registered risk limits trigger. Reassess at the next review.'],
        ['KEEP +5 / +10 / +15 / +25 / staged targets','Matched entries permit useful counterfactual comparisons, but costs, selection and delayed exits dominate.','Stable effects within entry version and liquidity/horizon strata, across less-correlated events, robust costs and held-out validation; not 20 events or p<0.05 alone.'],
        ['KEEP 8h cadence; REVISE eligible horizons','Complete print retrieval supports resting-limit estimates, not timely market exits.','Unresolved retrieval failure on the next check, worsening late exits, or a reliable tested scheduler/quote service warrants a new operational design.'],
        ['KEEP original trial boundary','Initial entries stop Dec 6 at 10:29 AM Eastern; existing exits continue.','Dec 4 review must explicitly register any new phase; otherwise exit-only monitoring. Never reset capital or losses.']]))
    x=r['inception'];section('Portfolio and review window',table(['Measure','Result'],[
        ['Data cutoff (Eastern)','Nov 20, 2026, 12:41 PM; review at 3:45 PM (~3.1h old)'],
        ['Equity / total starting capital',dollar(r['summary']['equity'])+' / $100,000'],
        ['Net P&L / total capital',dollar(x['marked_net'])+' / '+pct(x['marked_net']/100000)],
        ['Realized closed / open P&L',dollar(x['realized'])+' / '+dollar(x['open_pnl'])],
        ['Cumulative deployed outlay / net return',dollar(x['deployed_outlay'])+' / '+pct(x['marked_return_on_all_outlay'])],
        ['Closed outlay / net return',dollar(x['completed_outlay'])+' / '+pct(x['completed_return'])],
        ['Submitted / any entry / fully entered / closed',f"{x['submitted']} / {x['entered']} / {x['fully_entered']} / {x['closed']}"],
        ['Closed event identifiers / effective all-entry events',str(x['event_blocks'])+' / '+num(x['effective_events'])],
        ['Average win / average loss / expectancy',dollar(x['avg_win'])+' / '+dollar(x['avg_loss'])+' / '+dollar(x['expectancy'])],
        ['Profit factor / win rate (Wilson interval)',num(x['profit_factor'])+' / '+pct(x['win_rate'])+' ('+interval(x['win_ci'])+')'],
        ['Current / maximum sampled drawdown',pct(r['summary']['drawdown'])+' / '+pct(r['summary']['max_drawdown'])],
        ['Worst closed loss / worst-5% return mean',dollar(x['worst_pnl'])+' / '+pct(x['worst_5pct_mean'])],
        ['Last 14-day observed equity change',dollar(r['last14days']['observed_equity_change'])],
        ['Last 14-day closed cohort / realized',str(r['last14days']['closed_cohort']['closed'])+' / '+dollar(r['last14days']['closed_cohort']['realized'])]
    ])+p('Window: Nov 6, 12:41 PM to Nov 20, 12:41 PM Eastern. No quote exists exactly at the start; equity change uses the last preceding Nov 6, 11:14 AM snapshot ($99,974.53). The 74 closures in that window use whole-trade cost/P&L, not period-attributed returns. Inception includes the first two closures. All dollar results are simulated; open marks are bid-side liquidation estimates, not executed sales. Sampled drawdown can miss intrainterval losses.'))
    section('Horizon and execution comparisons',table(['Horizon','Closed / event IDs','Realized','Open P&L','Total net','Net / current allocation','Net / all outlay','Mean hold','>1h late','Settlement'],[
        [h,f"{v['closed']} / {v['event_blocks']}",dollar(v['realized']),dollar(v['open_pnl']),dollar(v['marked_net']),pct(v['marked_net']/({'day':45000,'month':22500,'long':22500}[h])),pct(v['marked_return_on_all_outlay']),num(v['hold_mean'])+'h',v['late_over_1h'],v['settlement_fallbacks']] for h,v in r['horizons'].items()])+p('Current allocations are $45k / $22.5k / $22.5k, with $10k reserve. Each horizon is split equally by entry mode. Current-allocation ratios are simple P&L denominators, not time-weighted returns: the owner changed allocations Nov 13. Same-day is mostly Bitcoin; monthly repeats a handful of macro events; long-horizon is one impeachment event. Expiration, assets, liquidity, holding period and entry version are confounded.')+table(['Sleeve','Closed / events','Any / submitted','Full / partial','Net','Realized','Fees','Win / loss avg','PF / expectancy','Hold mean / p90'],[
        [v['bucket'],f"{v['closed']} / {v['event_blocks']}",f"{v['entered']} / {v['submitted']}",f"{v['fully_entered']} / {v['partial_entries']}",dollar(v['marked_net']),dollar(v['realized']),dollar(v['fees']),dollar(v['avg_win'])+' / '+dollar(v['avg_loss']),num(v['profit_factor'])+' / '+dollar(v['expectancy']),num(v['hold_mean'])+' / '+num(v['hold_p90'])+'h'] for v in r['buckets']])+p('Any-entry rates include tiny, unpaired fills and are not full-basket fill rates. Recorded holding time starts at order opening; maker durations can include time waiting for entry. Across the ledger, 34 entries were partial, 32 had unequal bought quantities between legs. Five funded positions and one unfilled order remain. There are no currently closing baskets, but 57 trades recorded >1h exit lag; 25 same-day closures required settlement. Sparse trades alone are not collection failures.'))
    section('Rule versions and matched entries',table(['Entry version','Closed / events','Net including marks','Completed return'],[[v,f"{x['closed']} / {x['event_blocks']}",dollar(x['marked_net']),pct(x['completed_return'])] for v,x in r['by_version'].items()])+table(['Version','Paired closures / event IDs','Mean maker minus taker return'],[[v,len(ps),pct(statistics.mean(p['maker_return']-p['taker_return'] for p in ps))] for v in r['by_version'] if (ps:=[p for p in r['matched_execution_pairs'] if p['version']==v])])+p('26 matched event/time/version pairs (24 event IDs) closed in both entry modes. These are descriptive return differences on unequal actually filled quantities; conditioning on both sides filling and closing creates selection bias. No version contains 20 matched event blocks. Every sleeve/version bootstrap is withheld for inadequate blocks. No baseline promotion or sizing inference follows.'))
    rows=r['profit_analysis']['strata'][0]['rows']
    section('Profit targets: same entries, five alternatives',p('profit-targets-v1 remains frozen. These are mutually exclusive counterfactual policies, not five funded portfolios and never additive gains. All alternatives use the same source entry, entry fees and quantities; source entry mode is stratified, while target sells are resting limits in every alternative.')+table(['Target','Common closed / event IDs','Completed P&L','Net / outlay','All-position P&L','Fees','Net / trade','Before expiry','Late / settlement','Open'],[
        [v['label'],f"{v['matched_closed']} / {v['event_blocks']}",dollar(v['net_pnl']),pct(v['net_return']),dollar(v['marked_net_pnl']),dollar(v['fees']),dollar(v['expectancy']),pct(v['early_exit_rate']),f"{v['late_exits']} / {v['settlement_fallbacks']}",v['unresolved']] for v in rows])+p('32 enrolled sources; 28 closed in every policy, four unresolved. Common completed outlay is about $1,203.40. All-position results use all 32 priced sources and are negative for every policy: completed-only results hide open losses. Only 32 of 71 post-registration submitted entries qualified; three fully entered one-contract sources were explicitly excluded (T00042, T00062, T00079), while incomplete/unfilled entries are not enrolled. This favors liquid, fully filled baskets and underrepresents maker entries. No current enrolled source is excluded for missing marks/history; this does not prove that unavailable opportunities are unbiased.')+table(['Horizon / source mode','Closed / event IDs','+5% net','+10% net','+15% net','+25% net','Staged net','All-position +25%'],[
        [a['horizon']+' / '+a['entry_mode'],f"{a['rows'][0]['matched_closed']} / {a['rows'][0]['event_blocks']}",*[dollar(v['net_pnl']) for v in a['rows']],dollar(a['rows'][3]['marked_net_pnl'])] for a in r['profit_analysis']['strata'] if a['horizon']!='all'])+table(['Entry version','Closed / event IDs','+5%','+10%','+15%','+25%','Staged'],[
        [v,f"{a['strata'][0]['rows'][0]['matched_closed']} / {a['strata'][0]['rows'][0]['event_blocks']}",*[dollar(x['net_pnl']) for x in a['strata'][0]['rows']]] for v,a in r['profit_by_entry_version'].items() if a['strata'][0]['rows'][0]['assigned']])+p('The ranking changes by source-entry version: +25% led v3, whereas +5% slightly leads staged in v4. Neither version has 20 event blocks. Opportunity selection, post-Nov13 allocation and the prospective intraday pause prevent treating pooled future results as one stationary trial.'))
    section('Registered uncertainty and cost sensitivity',table(['Target','95% return CI','Difference vs +25%','95% difference CI','Holm p','Avg win / loss','PF','Double fees','Extra 1¢ exit cost'],[
        [v['label'],interval(v['return_ci']),pct(v['delta_vs_25']),interval(v['delta_ci']),num(v['p_holm']),dollar(v['average_win'])+' / '+dollar(v['average_loss']),num(v['profit_factor']),pct(v['double_fee_return']),pct(v['one_cent_exit_slippage_return'])] for v in rows])+p('Reproduced scripts/review_stats.py and profit_stats.analyze through the stored collector summary exactly. 2,000 paired event-cluster resamples; sign-flips assume exchangeable symmetric event effects; Holm covers four comparisons within each stratum only. All four adjusted pooled p-values are 1.00. The 20 nominal event blocks have only 9.23 outlay-weighted effective events (largest 18.28%); Bitcoin events share common drivers. Pooled intervals are exploratory, not independent validation or simultaneous coverage across 12 strata and repeated reviews. There are only 15 calendar entry dates across 14 elapsed days: no dependable day-cluster inference or covariance estimate. No Sharpe annualization, Kelly or tuning.')+p('All policies: 10/28 wins, Wilson 20.71%–54.17% (descriptive independence assumption); worst-5% empirical loss is 100% of entry cost. Mean holding 19.25h, median 11.25h, p90 35.77h. Fees consume roughly 7.4% of common outlay; either doubling fees or charging an extra cent on nonsettlement exits reverses the small pooled completed profit. These are accounting stress tests, not replays of new orders or queue assumptions. With zero assumed maker fills, affected entries would not exist; their downstream targets cannot simply be credited. Unknown queue priority prevents a validated alternative fill-probability estimate.'))
    section('Target recovery and execution audit',table(['Target','Tranches','Cash target recovered*','Limit target flag','Open partial exits','Remaining contracts','Open liquidation mark'],[
        [v['policy'],v['tranches'],v['cash_target_recovered'],v['limit_target_recovered'],v['open_partial_exits'],v['remaining_contracts'],dollar(v['open_mark'])] for v in r['profit_recovery']])+p('*Cash recovery includes all proceeds and can include settlement; it does not mean a successful early limit exit. Each policy has one source with an unattainable single-leg target. Limits are the smallest modeled cent price covering the whole tranche basket cost plus net target and maker fee, never silently capped. The staged split floors the first half and assigns remainder quantity/cost/fees to the second half; an odd lot is not exactly 50/50. Cent rounding overshoots nominal targets. Costs, fees and per-leg quantities sum back to the same original entry in every policy. No oversales or sale-before-entry were found.')+p('Within each alternative, all sources and tranches share 5% public-print liquidity and observed-book exit depth. Different alternatives each receive their own counterfactual budget; funded baseline and alternatives are not added. Fractional print credits accumulate before an integer fill, so one fill may reflect multiple prints. Tests cover shared volume, repeated prints, odd quantities, whole-basket recovery, unavailable targets, missing history and entry-time ambiguity. All 549 baseline/study backfilled fills reference archived prints (313 funded-ledger fills); timestamps are normalized before comparison. This supports ordered simulation, not actual execution or queue priority. Residual legs require the next observed book. Prints/OHLC cannot establish an executable historical market stop.'))
    c=r['cadence'];a=r['audit']
    section('Collection, timing and accounting',table(['Check','Observed evidence'],[
        ['History retrieval',f"{c['history_attempts']} trade-history attempts; {c['history_failures']} initial failures, recovered next run. Latest 4/4 complete; study blocked slices 0."],
        ['Archive evidence',f"{a['archived_observations']} observations; {a['archived_unique_prints']:,} unique archived prints; all 549 referenced fills located."],
        ['After 8h change',f"{c['checks_after_8h']} persisted checks; median gap {c['interval_median']:.2f}h, max {c['interval_max']:.2f}h; {c['intervals_over_9h']} intervals >9h."],
        ['Actions',f"41 success, 1 initial cancellation. 30 scheduled runs since cadence change versus 37 nominal due slots; 27 runs >1h after the most recent due slot."],
        ['Execution delays','41/43 same-day closures >1h late; max 22.40h. Monthly 16 late trades, including partial-entry expiry. Longer cadence is not a stop-loss service.'],
        ['Accounting','All six sleeve cash balances reconcile to initial cash + transfers − buys + sales; transfers net zero. Fee, cost, proceeds and inventory checks pass.'],
        ['Cap compliance',f"Largest combined all-leg entry outlay incl. fees {dollar(a['max_entry_outlay'])}; zero $2,000 violations."],
        ['Fees / estimated entry spread',dollar(x['fees'])+' fees; '+dollar(r['spread_estimate']['taker_entry_midpoint_drag'])+' taker entry drag vs observed midpoint (77/77 buy fills).'],
        ['All open marks fall to zero',dollar(r['stress']['all_open_marks_to_zero_equity'])+' equity; '+dollar(r['summary']['equity']-r['stress']['all_open_marks_to_zero_equity'])+' additional loss.'],
        ['Double already charged fees',dollar(r['stress']['double_realized_fees_equity'])+' equity.']
    ])+p('Cron remains 7 1,9,17 * * * UTC. Metadata does not expose each originating scheduled slot; the lateness calculation is a lower bound from the most recent due slot, and the seven-slot deficit cannot distinguish delayed versus dropped triggers. Github documents possible delayed/dropped schedules. Collection itself runs successfully; shortening cron alone does not repair unavailable executable books. No current unresolved failed/truncated history was found. The API client exhausts pagination or retains the checkpoint on errors; raw cursor/page manifests were not archived, so independent proof of exchange completeness is unavailable. Sparse trading is not labeled failure. Eight-hour collection already replaced 12 hours on Nov 8; that dated review remains intact.')+p('Open outlay totals $218.14; liquidation marks total $176.07, mostly monthly exposure. Largest event is 11.58% of cumulative deployed outlay; effective event count 13.15. Full-position loss scenarios and the 7.5% pause rule remain more defensible than an unstable covariance estimate. Fees are modeled, not a brokerage statement: current primary documents distinguish member precision and per-order rebates. We preserve the registered fee model and show stresses rather than retroactively alter losses. Exact total spread/adverse-selection drag is not separately identifiable from observed price movement.'))
    section('Sources and reproducibility','<ul>'+''.join('<li><a href="'+esc(url)+'">'+esc(title)+'</a></li>' for title,url in [
        ('Kalshi public trades: timestamps, aggressor and pagination','https://docs.kalshi.com/api-reference/market/get-trades'),
        ('Kalshi fee rounding: precision and order accumulators','https://docs.kalshi.com/getting_started/fee_rounding'),
        ('Kalshi published fee schedule','https://kalshi.com/docs/kalshi-fee-schedule.pdf'),
        ('GitHub scheduled workflow timing limitations','https://docs.github.com/en/actions/reference/workflows-and-actions/events-that-trigger-workflows#schedule'),
        ('Frozen machine-readable review evidence','2026-11-20.json'),
        ('GitHub Actions evidence','https://github.com/asre1212/kal/blob/main/data/research/2026-11-20-actions.json'),
        ('Authoritative source snapshot','https://github.com/asre1212/kal/tree/'+r['source_commit'])])+'</ul>'+p('Primary references checked November 20. No economic rule or fee coefficients were tuned. Audit reads ledger/archives only; 42 engine/statistics/audit tests passed after the prospective change. Exact changes: version v5, pause day_maker/day_taker, accurate allocation notes, visible pause/stale-gap notice and linked dated review. Collection cadence, all risk limits, profit hypotheses, owner allocation and existing trades remain intact.'))
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kal · November 20 review</title><style>body{font:16px/1.55 system-ui;background:#f6f7f2;color:#243127;margin:0}main{max-width:1180px;margin:auto;padding:28px 20px}h1{font-size:34px;line-height:1.2}h2{font-size:23px}section{background:white;border:1px solid #dce3d8;border-radius:14px;padding:22px;margin:22px 0}p{max-width:1000px}a{color:#366746}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:11px;text-align:left;border-bottom:1px solid #e5e9e2;vertical-align:top}th{background:#eef2e9}small{color:#61715f}</style><main><a href="../#research">← Dashboard</a><h1>Two weeks of evidence.<br>Execution timing comes first.</h1><small>November 20, 2026 · PAPER ONLY · Frozen 12:41 PM Eastern snapshot</small>'+''.join(body)+'</main></html>'

if __name__=='__main__':
    path=ROOT/'docs/reviews/2026-11-20.json'
    path.with_suffix('.html').write_text(render(json.loads(path.read_text())))
